/*
 * Signature entrances for the three brothers in the Family scene. Everything stays in the
 * paper world: ledger card, pop-up bars, a volvelle, punched tape, card gears, paper mosaic.
 * Every panel is drawn in a local PANEL_W × PANEL_H box and animated from `f` (frames since
 * that brother's introduction began) and `fps`.
 */

export const PANEL_W = 580;
export const PANEL_H = 560;

const spring = (f: number, start: number, dur = 20): number => {
  // soft landing with a small, damped overshoot (deterministic, no physics state)
  const t = Math.min(1, Math.max(0, (f - start) / dur));
  if (t <= 0) return 0;
  const e = 1 - Math.pow(1 - t, 3);
  return e + Math.sin(t * Math.PI) * 0.12 * (1 - t);
};

/** Paper card with a soft lift and a double gold rule. */
const Card: React.FC<{ fill?: string; rule?: string; children?: React.ReactNode }> = ({
  fill = palette.ivoryLight,
  rule = palette.gold,
  children,
}) => (
  <svg width={PANEL_W} height={PANEL_H} viewBox={`0 0 ${PANEL_W} ${PANEL_H}`} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
    <rect x={0} y={0} width={PANEL_W} height={PANEL_H} rx={8} fill={fill} filter="url(#lift)" />
    <rect x={9} y={9} width={PANEL_W - 18} height={PANEL_H - 18} rx={4} fill="none" stroke={rule} strokeWidth={1.4} />
    <rect x={15} y={15} width={PANEL_W - 30} height={PANEL_H - 30} rx={3} fill="none" stroke={rule} strokeWidth={0.6} opacity={0.6} />
    {children}
  </svg>
);

const Abs: React.FC<{ x: number; y: number; w?: number; style?: React.CSSProperties; children: React.ReactNode }> = ({ x, y, w, style, children }) => (
  <div style={{ position: "absolute", left: x, top: y, width: w, ...style }}>{children}</div>
);

