/** KPI tile: Hindi label + Hindi value, with a small English line beneath. */
const KPI_W = 168;
const KPI_H = 104;
const KpiTile: React.FC<{ x: number; y: number; t: number; label: Bi; value: Bi; valueSize?: number }> = ({
  x,
  y,
  t,
  label,
  value,
  valueSize = 36,
}) => {
  // flip about the vertical axis: back (foil-dotted) until half-way, then the front face
  const angle = (1 - t) * 180;
  const sx = Math.abs(Math.cos((angle * Math.PI) / 180));
  const front = angle < 90;
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: KPI_W,
        height: KPI_H,
        transform: `scaleX(${Math.max(0.02, sx)})`,
        opacity: t > 0 ? 1 : 0,
        borderRadius: 6,
        background: front ? palette.ivoryLight : palette.maroon,
        border: `1.5px solid ${palette.gold}`,
        boxShadow: "0 3px 6px rgba(42,23,18,0.18)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      {front ? (
        <>
          <div style={{ fontFamily: fonts.label, fontSize: 20, lineHeight: 1.3, color: palette.goldDeep }}>{label.hi}</div>
          <div style={{ fontFamily: fonts.display, fontWeight: 600, fontSize: valueSize, lineHeight: 1.3, color: palette.maroon, marginTop: -3 }}>{value.hi}</div>
          <div style={{ fontFamily: fonts.latin, fontStyle: "italic", fontWeight: 500, fontSize: 17, lineHeight: 1.1, color: palette.inkSoft, opacity: 0.85, whiteSpace: "nowrap" }}>
            {label.en} {value.en}
          </div>
        </>
      ) : (
        <svg width={KPI_W} height={KPI_H}>
          <rect width={KPI_W} height={KPI_H} fill="url(#dots-gold)" />
          <path d={`M84 ${KPI_H / 2 - 18} L102 ${KPI_H / 2} L84 ${KPI_H / 2 + 18} L66 ${KPI_H / 2} Z`} fill="none" stroke={palette.goldLight} strokeWidth={1.4} />
        </svg>
      )}
    </div>
  );
};

/** Paper volvelle: a pie disc turning under a fixed window, held by a brass split-pin. */
const Volvelle: React.FC<{ cx: number; cy: number; r: number; spin: number; show: number }> = ({ cx, cy, r, spin, show }) => {
  const seg = (a0: number, a1: number, fill: string) => {
    const p = (a: number) => [cx + Math.cos(((a - 90) * Math.PI) / 180) * r, cy + Math.sin(((a - 90) * Math.PI) / 180) * r];
    const [x0, y0] = p(a0);
    const [x1, y1] = p(a1);
    return <path d={`M${cx} ${cy} L${x0} ${y0} A${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${x1} ${y1} Z`} fill={fill} />;
  };
  return (
    <g opacity={show} transform={`translate(${cx} ${cy}) scale(${0.6 + 0.4 * show}) translate(${-cx} ${-cy})`}>
      <circle cx={cx} cy={cy + 3} r={r + 8} fill={palette.ink} opacity={0.12} />
      <circle cx={cx} cy={cy} r={r + 8} fill={palette.ivory} stroke={palette.gold} strokeWidth={1.2} />
      {new Array(24).fill(0).map((_, i) => {
        const a = (i / 24) * Math.PI * 2;
        return (
          <path
            key={i}
            d={`M${cx + Math.cos(a) * (r + 3)} ${cy + Math.sin(a) * (r + 3)} L${cx + Math.cos(a) * (r + 7)} ${cy + Math.sin(a) * (r + 7)}`}
            stroke={palette.goldDeep}
            strokeWidth={1}
          />
        );
      })}
      <g transform={`rotate(${spin} ${cx} ${cy})`}>
        {seg(0, 150, palette.gold)}
        {seg(150, 250, palette.maroon)}
        {seg(250, 360, palette.green)}
        <circle cx={cx} cy={cy} r={r} fill="none" stroke={palette.ivoryLight} strokeWidth={1.5} />
        <path d={`M${cx} ${cy} L${cx} ${cy - r} M${cx} ${cy} L${cx + r * 0.5} ${cy + r * 0.866}`} stroke={palette.ivoryLight} strokeWidth={1.5} />
      </g>
      {/* pointer tab */}
      <path d={`M${cx - 8} ${cy - r - 16} L${cx + 8} ${cy - r - 16} L${cx} ${cy - r + 2} Z`} fill={palette.maroon} />
      <circle cx={cx} cy={cy} r={7} fill="#B8904A" />
      <circle cx={cx} cy={cy} r={3} fill={palette.goldDeep} />
      <circle cx={cx - 2} cy={cy - 2} r={1.6} fill="#F3E2B4" />
    </g>
  );
};

