const gearPath = (r: number, teeth: number): string => {
  const pts: string[] = [];
  const n = teeth * 4;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const rr = i % 4 < 2 ? r : r * 0.8;
    pts.push(`${(Math.cos(a) * rr).toFixed(2)} ${(Math.sin(a) * rr).toFixed(2)}`);
  }
  return `M${pts.join(" L")} Z`;
};

const Gear: React.FC<{ x: number; y: number; r: number; teeth: number; rot: number; show: number }> = ({ x, y, r, teeth, rot, show }) => (
  <g transform={`translate(${x} ${y}) scale(${show}) rotate(${rot})`} opacity={show}>
    <path d={gearPath(r, teeth)} fill={palette.ink} opacity={0.12} transform="translate(2 3)" />
    <path d={gearPath(r, teeth)} fill={palette.ivory} stroke={palette.gold} strokeWidth={1.4} strokeLinejoin="round" />
    <circle r={r * 0.55} fill="none" stroke={palette.goldLight} strokeWidth={1} />
    {[0, 60, 120, 180, 240, 300].map((a) => (
      <circle key={a} cx={Math.cos((a * Math.PI) / 180) * r * 0.36} cy={Math.sin((a * Math.PI) / 180) * r * 0.36} r={r * 0.08} fill={palette.goldDeep} opacity={0.5} />
    ))}
    <circle r={r * 0.16} fill="#B8904A" />
    <circle r={r * 0.07} fill={palette.goldDeep} />
  </g>
);

