/* ─────────────────────────────── Gamer — paper mosaic ─────────────────────────────── */

const CELL = 20;
export const PIXEL_W = 420;
const COLS = PIXEL_W / CELL; // 21
const ROWS = PANEL_H / CELL; // 28

const CLOUDS: [number, number][] = [
  [3, 9], [4, 9], [5, 9], [6, 9], [4, 8], [5, 8],
  [13, 12], [14, 12], [15, 12], [16, 12], [17, 12], [14, 11], [15, 11], [16, 11],
];
const HEARTS: [number, number][] = [
  [4, 15], [6, 15], [3, 16], [4, 16], [5, 16], [6, 16], [7, 16], [4, 17], [5, 17], [6, 17], [5, 18],
];

const cellColor = (i: number, j: number): string => {
  if (i === 0 || j === 0 || i === COLS - 1 || j === ROWS - 1) return (i + j) % 2 ? "#C9A45C" : "#B48A45";
  if (i === 1 || j === 1 || i === COLS - 2 || j === ROWS - 2) return "#8C4A6E";
  if (j >= ROWS - 5) return j === ROWS - 5 ? "#9AA27E" : (i + j) % 2 ? "#6D7957" : "#74805D";
  if (CLOUDS.some(([x, y]) => x === i && y === j)) return "#FFFDF6";
  if (HEARTS.some(([x, y]) => x === i && y === j)) return "#C98B8B";
  return (i + j) % 2 ? "#F4E6CF" : "#EFDDC1";
};

const PLAYER_JOINED = bi("PLAYER 3 HAS JOINED");
const LEVEL_UP = bi("LEVEL UP!");
/** The pixel face has no Devanagari: Hindi lines use Martel ExtraBold, set tight like the 8-bit type. */
const PIXEL_HI: React.CSSProperties = { fontFamily: "Martel, serif", fontWeight: 800, lineHeight: 1.4, whiteSpace: "nowrap" };

/** Pranab — the panel assembles from tiny paper squares, then the game UI drops in. */
export const PixelPanel: React.FC<{ f: number; landAt: number; landX?: number }> = ({ f, landAt, landX = 280 }) => {
  const cells = useMemo(() => {
    const out: { i: number; j: number; c: string; d: number }[] = [];
    for (let j = 0; j < ROWS; j++)
      for (let i = 0; i < COLS; i++) {
        const dist = Math.hypot(i - COLS * 0.66, j - ROWS * 0.55) / 24;
        out.push({ i, j, c: cellColor(i, j), d: dist * 14 + random(`px-${i}-${j}`) * 8 });
      }
    return out;
  }, []);
  const W = PIXEL_W;
  const banner = prog(f, 16, 14, EASE.out);
  const xp = prog(f, 26, 26, EASE.inOut);
  const burst = prog(f, landAt, 22, EASE.out);
  const slots = 9;
  return (
    <div style={{ position: "absolute", inset: 0 }}>
      <svg width={W} height={PANEL_H} viewBox={`0 0 ${W} ${PANEL_H}`} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
        <rect x={4} y={6} width={W} height={PANEL_H} fill={palette.ink} opacity={0.12 * prog(f, 12, 10)} />
        {cells.map(({ i, j, c, d }) => {
          const s = prog(f, d, 8, EASE.out);
          if (s <= 0) return null;
          const x = i * CELL + CELL / 2;
          const y = j * CELL + CELL / 2;
          const k = (CELL - 1) * s;
          return <rect key={`${i}-${j}`} x={x - k / 2} y={y - k / 2} width={k} height={k} fill={c} />;
        })}
        {/* XP bar filling with marigold petals */}
        <g opacity={prog(f, 22, 8)}>
          <rect x={86} y={126} width={300} height={34} fill="#2B2A30" />
          <rect x={90} y={130} width={292} height={26} fill="#F7EEDB" />
          {new Array(slots).fill(0).map((_, k) => {
            const on = Math.min(1, Math.max(0, xp * slots - k));
            return (
              <g key={k} opacity={on}>
                <rect x={92 + k * 32.2} y={132} width={30} height={22} fill={palette.turmeric} opacity={0.35} />
                <Petal x={95 + k * 32.2} y={143 + (1 - on) * -18} rot={-12 + (k % 3) * 10} s={1.3} color={k % 2 ? palette.marigold : palette.turmeric} />
              </g>
            );
          })}
        </g>
        {/* LEVEL UP star-burst */}
        {burst > 0 ? (
          <g transform={`translate(${landX} 206)`}>
            {new Array(12).fill(0).map((_, k) => {
              const a = (k / 12) * Math.PI * 2;
              const r0 = 44 + burst * 30;
              return (
                <g key={k}>
                  {[0, 1, 2].map((q) => (
                    <rect
                      key={q}
                      x={Math.cos(a) * (r0 + q * 12) * 1.3 - 4}
                      y={Math.sin(a) * (r0 + q * 12) * 0.62 - 4}
                      width={8 - q * 2}
                      height={8 - q * 2}
                      fill={k % 2 ? palette.gold : palette.marigold}
                      opacity={(1 - q * 0.3) * Math.min(1, burst * 3)}
                    />
                  ))}
                </g>
              );
            })}
          </g>
        ) : null}
      </svg>
      <Abs x={0} y={46} w={W} style={{ textAlign: "center", opacity: banner, transform: `translateY(${(1 - banner) * -40}px)` }}>
        <div style={{ fontFamily: fonts.pixel, fontSize: 17, lineHeight: 1.3, color: "#2B2A30", textShadow: `3px 3px 0 ${palette.goldLight}`, whiteSpace: "nowrap" }}>
          {PLAYER_JOINED.en}
        </div>
        <div style={{ ...PIXEL_HI, fontSize: 25, marginTop: 4, color: "#2B2A30", textShadow: `2px 2px 0 ${palette.goldLight}` }}>{PLAYER_JOINED.hi}</div>
      </Abs>
      <Abs x={46} y={135} style={{ opacity: prog(f, 22, 8) }}>
        <span style={{ fontFamily: fonts.pixel, fontSize: 15, color: "#2B2A30" }}>XP</span>
      </Abs>
      <Abs
        x={landX - 200}
        y={172}
        w={400}
        style={{
          textAlign: "center",
          opacity: Math.min(1, burst * 2.5),
          transform: `scale(${0.6 + 0.4 * spring(f, landAt, 14)})`,
        }}
      >
        <div style={{ fontFamily: fonts.pixel, fontSize: 26, lineHeight: 1.3, color: palette.maroon, textShadow: `3px 3px 0 ${palette.goldPale}` }}>{LEVEL_UP.en}</div>
        <div style={{ ...PIXEL_HI, fontSize: 26, marginTop: 2, color: palette.maroon, textShadow: `2px 2px 0 ${palette.goldPale}` }}>{LEVEL_UP.hi}</div>
      </Abs>
    </div>
  );
};


/** Paper coin that pops up with "+100" and floats away (drawn in scene/local px). */
export const PopCoin: React.FC<{ x: number; y: number; f: number }> = ({ x, y, f }) => {
  if (f < 0 || f > 34) return null;
  const up = prog(f, 0, 14, EASE.out);
  const fade = 1 - prog(f, 22, 12, EASE.in);
  const flip = Math.abs(Math.cos(f * 0.35));
  return (
    <div style={{ position: "absolute", left: x - 40, top: y - 60 * up - 30, width: 80, textAlign: "center", opacity: fade }}>
      <svg width={40} height={40} viewBox="-20 -20 40 40" style={{ display: "block", margin: "0 auto", transform: `scaleX(${Math.max(0.15, flip)})` }}>
        <circle r={17} fill="url(#foil)" />
        <circle r={12} fill="none" stroke={palette.goldDeep} strokeWidth={1.4} />
        <rect x={-3} y={-7} width={6} height={14} fill={palette.goldDeep} />
      </svg>
      <div style={{ ...PIXEL_HI, fontSize: 20, color: palette.goldDeep, marginTop: 2 }}>{hiDigits("+100")}</div>
    </div>
  );
};

