/* ─────────────────────────────── Name plates ─────────────────────────────── */

/*
 * Bilingual plate text: Hindi name above its English, then the Hindi role above its English.
 * PLATE_TEXT_H is the height of that stack — plates size themselves around it.
 */
const PLATE_TEXT_H = 112;
const PlateText: React.FC<{ name: string; role: string; light?: boolean }> = ({ name, role, light }) => {
  const ink = light ? palette.ivoryLight : palette.maroon;
  const soft = light ? palette.goldPale : palette.inkSoft;
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 3 }}>
      <Dual
        text={bi(name)}
        style={{ fontFamily: fonts.label, fontSize: 27, lineHeight: 1.3, color: ink, whiteSpace: "nowrap" }}
        enStyle={{ fontSize: 20, fontWeight: 600, color: ink, opacity: 0.8, whiteSpace: "nowrap" }}
        gap={-2}
      />
      <Dual
        text={bi(role)}
        style={{ fontFamily: fonts.display, fontSize: 24, lineHeight: 1.3, color: soft, whiteSpace: "nowrap" }}
        enStyle={{ fontSize: 19, color: soft, whiteSpace: "nowrap" }}
        gap={-2}
      />
    </div>
  );
};

/** Desk placard: ivory face with a gold rule on a walnut wedge base. */
export const PlacardPlate: React.FC<{ name: string; role: string; w?: number }> = ({ name, role, w = 290 }) => {
  const face = PLATE_TEXT_H + 26; // bottom of the ivory face
  const h = face + 14;
  return (
    <div style={{ position: "relative", width: w, height: h }}>
      <svg width={w} height={h} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
        <path d={`M10 ${face + 2} L${w - 10} ${face + 2} L${w} ${h} L0 ${h} Z`} fill="#5A3A2A" />
        <rect x={0} y={face} width={w} height={3} fill={palette.gold} />
        <path d={`M8 4 L${w - 8} 4 L${w - 4} ${face} L4 ${face} Z`} fill={palette.ivoryLight} filter="url(#lift-sm)" />
        <path d={`M15 10 L${w - 15} 10 L${w - 12} ${face - 6} L12 ${face - 6} Z`} fill="none" stroke={palette.gold} strokeWidth={1.2} />
        {[
          [22, 18],
          [w - 22, 18],
        ].map(([x, y]) => (
          <circle key={x} cx={x} cy={y} r={2.6} fill="url(#foil)" />
        ))}
      </svg>
      <div style={{ position: "absolute", left: 0, right: 0, top: 13, textAlign: "center" }}>
        <PlateText name={name} role={role} />
      </div>
    </div>
  );
};

