/** Game nameplate: plum banner with stepped (pixel) corners, gold border and a P3 tag. */
export const GamePlate: React.FC<{ name: string; role: string; w?: number }> = ({ name, role, w = 290 }) => {
  const h = PLATE_TEXT_H + 30;
  const s = 6;
  const step = (inset: number) =>
    `M${inset + s * 2} ${inset} L${w - inset - s * 2} ${inset} L${w - inset - s * 2} ${inset + s} L${w - inset - s} ${inset + s} L${w - inset - s} ${inset + s * 2} L${w - inset} ${inset + s * 2}
     L${w - inset} ${h - inset - s * 2} L${w - inset - s} ${h - inset - s * 2} L${w - inset - s} ${h - inset - s} L${w - inset - s * 2} ${h - inset - s} L${w - inset - s * 2} ${h - inset}
     L${inset + s * 2} ${h - inset} L${inset + s * 2} ${h - inset - s} L${inset + s} ${h - inset - s} L${inset + s} ${h - inset - s * 2} L${inset} ${h - inset - s * 2}
     L${inset} ${inset + s * 2} L${inset + s} ${inset + s * 2} L${inset + s} ${inset + s} L${inset + s * 2} ${inset + s} Z`;
  return (
    <div style={{ position: "relative", width: w, height: h }}>
      <svg width={w} height={h} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
        <path d={step(0)} fill={palette.gold} transform="translate(3 4)" opacity={0.35} />
        <path d={step(0)} fill={palette.goldLight} />
        <path d={step(3)} fill="#5A2A48" />
        <path d={step(8)} fill="none" stroke={palette.gold} strokeWidth={1} strokeDasharray="4 4" />
      </svg>
      <div
        style={{
          position: "absolute",
          left: -14,
          top: -12,
          padding: "5px 6px 4px",
          background: palette.turmeric,
          border: `2px solid #2B2A30`,
          fontFamily: fonts.pixel,
          fontSize: 11,
          color: "#2B2A30",
        }}
      >
        P3
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 13, textAlign: "center" }}>
        <PlateText name={name} role={role} light />
      </div>
    </div>
  );
};
